import openpyxl

wb = openpyxl.load_workbook('pwt110.xlsx', read_only=True)
data_sheet = wb['Data']

headers = []
for cell in data_sheet[1]:
    headers.append(cell.value)

country_idx = headers.index('countrycode')
year_idx = headers.index('year')
rnna_idx = headers.index('rnna')
rgdpna_idx = headers.index('rgdpna')

georgia_data = []
for row in data_sheet.iter_rows(min_row=2, values_only=True):
    if row[country_idx] == 'GEO':
        georgia_data.append({
            'year': row[year_idx],
            'rnna': row[rnna_idx],
            'rgdpna': row[rgdpna_idx]
        })

for entry in georgia_data:
    if 2000 <= entry['year'] <= 2023:
        print(f"{entry['year']}, {entry['rnna']}, {entry['rgdpna']}")
